import{_ as t,o as r,c as o,ah as i}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Recruiting certified profiles","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/entreprises/recrutement.md","filePath":"src/en/guide/entreprises/recrutement.md"}'),n={name:"en/guide/entreprises/recrutement.md"};function s(a,e,l,p,c,d){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="recruiting-certified-profiles" tabindex="-1">Recruiting certified profiles <a class="header-anchor" href="#recruiting-certified-profiles" aria-label="Permalink to &quot;Recruiting certified profiles&quot;">​</a></h1><p>NextBoxx connects companies with its <strong>certified learners</strong> who wish it, for an internship, a work-study placement, an assignment or a recruitment.</p><h2 id="submitting-a-request" tabindex="-1">Submitting a request <a class="header-anchor" href="#submitting-a-request" aria-label="Permalink to &quot;Submitting a request&quot;">​</a></h2><p>In <strong>Journeys → My company requests → New request</strong>, choose the type:</p><table tabindex="0"><thead><tr><th>Type</th><th>Specific fields</th></tr></thead><tbody><tr><td><strong>Placement</strong></td><td>Internship, work-study or assignment; skills sought; wished start; length in months; location</td></tr><tr><td><strong>Recruitment</strong></td><td>Job title; contract (permanent or fixed-term); location; indicative salary (optional); wished hiring date</td></tr></tbody></table><p>In both cases, also give the company name, the <strong>number of profiles sought</strong> (1 to 20), a target program (optional), a message, and whether you want <strong>support</strong>: NextBoxx then follows the integration of each retained profile, for an additional lump sum per profile.</p><p>The &quot;My company requests&quot; entry is visible to every personal account, even before the first request. The Partnerships Officer is notified of your request.</p><h2 id="the-proposed-profiles" tabindex="-1">The proposed profiles <a class="header-anchor" href="#the-proposed-profiles" aria-label="Permalink to &quot;The proposed profiles&quot;">​</a></h2><p>The Partnerships Officer proposes to you, in one or several goes, <strong>certified and visible</strong> profiles: learners who have chosen to make themselves visible to companies. For each, you first see their <strong>first name and the initial of their last name</strong>, their <strong>certificates</strong> (program, mention, date) and their <strong>presentation</strong>.</p><p>For each profile, you choose <strong>Retain</strong> or <strong>Decline</strong> (the Officer can also record it for you).</p><ul><li>A <strong>retained</strong> profile reveals to you the person&#39;s <strong>name, e-mail address, phone and CV</strong>, and they are told of it.</li><li>A profile that withdraws (because the person hides themselves) leaves the pending proposals; a profile already retained stays shared.</li></ul><h2 id="confirmation-and-invoice" tabindex="-1">Confirmation and invoice <a class="header-anchor" href="#confirmation-and-invoice" aria-label="Permalink to &quot;Confirmation and invoice&quot;">​</a></h2><p>As soon as at least one profile is retained, the Officer confirms the <strong>placement</strong>. An invoice is then issued to your company name, <strong>due in 30 days</strong>. It counts, <strong>per retained profile</strong>:</p><ul><li>the placement lump sum;</li><li>the support lump sum, if you asked for it.</li></ul><p>The request becomes &quot;Accepted&quot; and profiles still pending are closed as not retained. If no profile fits, the Officer closes the request, with no invoice.</p><p>Reminders and follow-up of this invoice follow the usual timeline, <strong>with no access suspension</strong>.</p>',16)])])}const f=t(n,[["render",s]]);export{u as __pageData,f as default};
